//! Candidate eligibility is independent of validity and form no-validate flags.
use super::*;
fn start(html:&str,source:&str)->(Document,Forms,Page){let mut d=crate::html::parse(html);d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://control-eligibility.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);let out=p.start(&mut d,&mut f,&[Script{node:0,label:"Native candidate eligibility".into(),source:source.into()}]);assert_eq!(out.errors,0,"{}",p.report());(d,f,p)}
#[test]
fn control_eligibility_canonical_readonly_getters_and_current_native_state(){
 start("<form id=form novalidate><fieldset disabled><legend><input id=legend></legend><input id=blocked></fieldset><input id=input required><button id=button>Submit</button><textarea id=area required></textarea><select id=select required><option value=''>Pick</option></select><datalist><input id=listed required></datalist></form>","var ids=['input','button','area','select'],constructors=[HTMLInputElement,HTMLButtonElement,HTMLTextAreaElement,HTMLSelectElement];for(var n=0;n<ids.length;n++){var x=document.getElementById(ids[n]),P=constructors[n].prototype,d=Object.getOwnPropertyDescriptor(P,'willValidate');if(!d||typeof d.get!=='function'||d.set!==undefined||d.get.name!=='get willValidate'||d.get.length!==0||!d.enumerable||!d.configurable||Object.prototype.hasOwnProperty.call(x,'willValidate')||x.willValidate!==true)throw 'canonical '+ids[n];x.willValidate=false;if(x.willValidate!==true)throw 'readonly';var denied=false;try{(function(){'use strict';x.willValidate=false;})();}catch(e){denied=e instanceof TypeError;}if(!denied)throw 'strict readonly';denied=false;try{d.get.call({});}catch(e){denied=e instanceof TypeError;}if(!denied)throw 'brand';x.disabled=true;if(x.willValidate!==false)throw 'disabled';x.disabled=false;if(x.willValidate!==true)throw 'enabled';}if(document.getElementById('legend').willValidate!==true||document.getElementById('blocked').willValidate!==false||document.getElementById('listed').willValidate!==false)throw 'native ancestors';var input=document.getElementById('input'),area=document.getElementById('area'),button=document.getElementById('button');input.readOnly=true;area.readOnly=true;if(input.willValidate||area.willValidate)throw 'readonly candidate';input.readOnly=false;area.readOnly=false;button.type='button';if(button.willValidate)throw 'button state';button.type='submit';if(!button.willValidate)throw 'submit candidate';");
}
#[test]
fn control_eligibility_datalist_is_excluded_by_shared_required_validation(){
 let(d,f,_)=start("<form id=form><input name=q value=Ready><datalist><input id=listed name=listed required></datalist></form>","var form=document.getElementById('form');form.addEventListener('invalid',function(){throw 'barred field event';},true);if(form.checkValidity()!==true||form.reportValidity()!==true)throw 'barred validation';");let form=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("form")).unwrap();assert!(f.validate_submission(&d,form,None).is_ok());
}

#[test]
fn control_eligibility_input_state_matrix_is_metadata_without_validity_claims(){
 for state in ["text","search","tel","url","email","password","number","range","color","date","datetime-local","month","week","time","file","checkbox","radio","submit","image","reset","button","hidden","invalid"]{
  let barred=matches!(state,"hidden"|"reset"|"button");let readonly_applies=!matches!(state,"checkbox"|"radio"|"file"|"range"|"color"|"image"|"submit");let html=format!("<input id=plain type='{state}'><input id=read type='{state}' readonly><input id=off type='{state}' disabled>");let source=format!("if(document.getElementById('plain').willValidate!=={}||document.getElementById('read').willValidate!=={}||document.getElementById('off').willValidate!==false)throw 'state {state}';",!barred,!barred&&!readonly_applies);start(&html,&source);
 }
}
#[test]
fn control_eligibility_button_auto_states_agree_with_canonical_type(){
 let(doc,_,_)=start("<button id=auto>Auto</button><button id=command commandfor=target>Command</button><button id=invalid type=invalid command=toggle>Command</button><button id=submit type=submit commandfor=target>Submit</button><button id=reset type=reset>Reset</button><button id=plain type=button>Plain</button>","for(var id of ['auto','command','invalid','submit','reset','plain']){var b=document.getElementById(id);if(b.willValidate!==(b.type==='submit'))throw 'Auto eligibility '+id;}");let auto=(0..doc.nodes.len()).find(|&n|doc.attr(n,"id")==Some("auto")).unwrap();let submit=(0..doc.nodes.len()).find(|&n|doc.attr(n,"id")==Some("submit")).unwrap();assert!(!forms::validation_candidate(&doc,auto,false,false,true));assert!(forms::validation_candidate(&doc,submit,false,false,true));
}
#[test]
fn control_eligibility_fresh_detached_controls_and_author_shadows_keep_identity(){
 start("<body></body>","var tags=['input','button','select','textarea'],constructors=[HTMLInputElement,HTMLButtonElement,HTMLSelectElement,HTMLTextAreaElement];for(var i=0;i<tags.length;i++){var x=document.createElement(tags[i]),P=constructors[i].prototype,d=Object.getOwnPropertyDescriptor(P,'willValidate');if(!x.willValidate||!d.get.call(x)||x.isConnected)throw 'fresh detached '+tags[i];Object.defineProperty(x,'willValidate',{value:'own',configurable:true});if(x.willValidate!=='own'||d.get.call(x)!==true)throw 'own shadow';delete x.willValidate;Object.defineProperty(P,'willValidate',{value:'prototype',configurable:true});if(x.willValidate!=='prototype'||d.get.call(x)!==true)throw 'prototype shadow';delete P.willValidate;if(x.willValidate!==undefined||d.get.call(x)!==true)throw 'deleted canonical';Object.defineProperty(P,'willValidate',d);if(x.willValidate!==true||Object.prototype.hasOwnProperty.call(x,'willValidate'))throw 'restore';}");
}
#[test]
fn control_eligibility_exact_brands_include_genuine_inert_controls(){
 start("<input id=input><button id=button></button><textarea id=area></textarea><select id=select></select>","var tags=['input','button','textarea','select'],classes=[HTMLInputElement,HTMLButtonElement,HTMLTextAreaElement,HTMLSelectElement],ids=['input','button','area','select'];for(var i=0;i<tags.length;i++){var getter=Object.getOwnPropertyDescriptor(classes[i].prototype,'willValidate').get,denied=false;try{getter.call(document.getElementById(ids[(i+1)%4]));}catch(e){denied=e instanceof TypeError;}if(!denied)throw 'concrete brand';var inert=document.implementation.createHTMLDocument('inert').createElement(tags[i]);if(getter.call(inert)!==true)throw 'genuine inert candidate';denied=false;try{getter.call(Object.create(classes[i].prototype));}catch(e){denied=e instanceof TypeError;}if(!denied)throw 'forged brand';}");
}
#[test]
fn control_eligibility_work_deadline_refusal_and_allocation_free_storage_read_preserve_state(){
 for mode in 0..3{
  let(mut d,mut f,mut p)=start("<form><input id=input name=q value=Seed required></form>","");let node=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("input")).unwrap();let object=node_handle(node);let before=format!("{:?}",d.nodes);let value=f.controls[&node].value.text();let retained_limit=p.state.retained_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};let retained=p.state.retained;let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.control_eligibility_get(object);if mode==1{assert!(matches!(result,Ok(Value::Bool(true))));assert_eq!(p.state.retained,retained);}else{assert!(result.is_err(),"mode {mode}");}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(f.controls[&node].value.text(),value);assert_eq!(p.take_validation_report(),None);assert!(p.state.form_requests.is_empty());assert!(p.state.form_validations.is_empty());assert!(p.state.synthetic_dispatches.is_empty());p.state.retained_limit=retained_limit;p.begin_job();assert!(matches!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.control_eligibility_get(object).unwrap(),Value::Bool(true)));
 }
}
#[test]
fn control_eligibility_saved_child_getter_authority_refuses_and_recovers(){
 let(mut d,mut f,mut p)=start("<body><input id=input></body>","var x=document.getElementById('input'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var getter=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLInputElement.prototype,'willValidate').get;if(getter.call(x)!==true)throw 'saved getter';");let before=format!("{:?}",d.nodes);p.set_location(&crate::navigation::address("https://foreign-eligibility.test/",&crate::navigation::Location::home()).unwrap());p.begin_job();let error=p.runtime.execute("getter.call(x);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);p.set_location(&crate::navigation::address("https://control-eligibility.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();p.runtime.execute("if(getter.call(x)!==true)throw 'saved recovery';",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();
}
